export const guideData="/* Original SHIFT editorial content. Linked sources checked 12 October 2026. */\nwindow.SHIFT_DATA = {\n  sources: {\n    balanced: {name:'NHS · Eating a balanced diet',url:'https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/',date:'Page reviewed 30 June 2026',scope:'General UK food-group guidance.'},\n    fibre: {name:'NHS · Getting more fibre',url:'https://www.nhs.uk/live-well/eat-well/digestive-health/how-to-get-more-fibre-into-your-diet/',date:'Page reviewed 2 March 2026',scope:'Adult fibre guidance; food quantities vary.'},\n    vitaminD: {name:'NHS · Vitamin D',url:'https://www.nhs.uk/conditions/vitamins-and-minerals/vitamin-d/',date:'Page reviewed 3 August 2020; displayed review due date has passed',scope:'UK daily and seasonal guidance; individual advice can differ.'},\n    vegan: {name:'NHS · The vegan diet',url:'https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/the-vegan-diet/',date:'Page reviewed 5 June 2026',scope:'Planning, fortified foods and nutrients to consider.'},\n    b12: {name:'NIH ODS · Vitamin B12',url:'https://ods.od.nih.gov/factsheets/VitaminB12-Consumer/',date:'Updated 15 December 2023',scope:'Dietary sources, absorption problems and the limits of energy claims; UK diet context uses NHS guidance.'},\n    iron: {name:'NHS · Iron',url:'https://www.nhs.uk/conditions/vitamins-and-minerals/iron/',date:'Page reviewed 3 August 2020; displayed review due date has passed',scope:'Food sources and risks of excessive iron.'},\n    minerals: {name:'NHS · Other vitamins and minerals',url:'https://www.nhs.uk/conditions/vitamins-and-minerals/others/',date:'Older official page; not treated as new research',scope:'Magnesium and zinc food sources and excess-dose cautions.'},\n    vitamins: {name:'NHS · Vitamins and minerals overview',url:'https://www.nhs.uk/conditions/vitamins-and-minerals/',date:'Page reviewed 3 August 2020; displayed review due date has passed',scope:'Most people can get needed nutrients through a varied diet; some need supplements.'},\n    sport: {name:'BDA · Sport and exercise',url:'https://www.bda.uk.com/resource/sport-exercise-nutrition.html',date:'Resource © May 2026; review due May 2029',scope:'Protein, food and training context; general advice, not a personal target.'},\n    creatine: {name:'NIH ODS · Exercise and athletic performance',url:'https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/',date:'Research synthesis; checked 12 October 2026, not newly published evidence',scope:'Creatine evidence mainly for repeated, high-intensity effort; evidence on ingredients does not validate blends.'},\n    omega: {name:'Cochrane · Omega-3 and cardiovascular disease',url:'https://www.cochrane.org/evidence/CD003177_omega-3-intake-cardiovascular-disease',date:'Published 29 February 2020; evidence searches through 2019',scope:'86 trials; outcome-specific results, not a blanket prevention claim.'},\n    omegaSafety: {name:'NIH ODS · Omega-3 fatty acids',url:'https://ods.od.nih.gov/factsheets/Omega3FattyAcids-Consumer/',date:'Updated 18 July 2022',scope:'Algal-oil formats and potential medicine interactions; not a UK dose recommendation.'},\n    sleep: {name:'NCCIH · Magnesium and sleep',url:'https://www.nccih.nih.gov/health/in-the-news-magnesium-supplements-for-sleep-disorders',date:'Updated January 2024',scope:'Limited, inconsistent and often low-quality sleep evidence.'},\n    probiotics: {name:'NHS · Probiotics',url:'https://www.nhs.uk/tests-and-treatments/probiotics/',date:'Page reviewed 24 November 2022; displayed review due date has passed',scope:'Some specific uses may help; products and strains are not interchangeable.'},\n    supplements: {name:'BDA · Supplements',url:'https://www.bda.uk.com/resource/supplements.html',date:'© May 2022; page says currently under review',scope:'Food-first approach, label checks, interactions and overlapping nutrients.'},\n    safety: {name:'NHS SPS · Using food supplements',url:'https://sps.nhs.uk/articles/using-food-supplements/',date:'Published 26 August 2025; updated 5 September 2025',scope:'Quality and risk differ from medicines; intended for professional practice.'},\n    weight: {name:'NIH ODS · Supplements for weight loss',url:'https://ods.od.nih.gov/factsheets/WeightLoss-Consumer/',date:'Official evidence overview; checked 12 October 2026',scope:'Limited evidence, possible harms and interactions. US regulation is not UK regulation.'},\n    fatigue: {name:'NHS · Tiredness and fatigue',url:'https://www.nhs.uk/symptoms/tiredness-and-fatigue/',date:'Page reviewed 2 June 2023; displayed review due date has passed',scope:'Persistent or unexplained tiredness needs assessment.'},\n    glp1: {name:'BDA · Eating and living well with medications for obesity',url:'https://www.bda.uk.com/food-health/glp-1-obesity-medications.html',date:'Main guide © February 2026; review due 2027',scope:'Dietetic advice for GLP-1-type medicines; not Orlistat. Manufacturer funding disclosed by BDA, with no input into content.'}\n  },\n  goals: {\n    basics:{title:'Start with the meals you already eat.',body:'A varied diet covers a lot of ground. Pick one meal to improve before making a supplement stack.',food:['Include a protein food and a starchy food.','Add fruit or veg; vary your choices through the week.'],focus:['vitamin-d','b12','multivitamin'],action:'food'},\n    weight:{title:'Make smaller meals count.',body:'A supplement is not a shortcut to lasting weight management. Put useful food in the space you have.',food:['Keep a protein food in your meals.','Keep variety rather than cutting out whole food groups.'],focus:['protein','vitamin-d','fat-burners'],action:'food'},\n    strength:{title:'Food supports the training.',body:'Adequate food and regular resistance training come first. Protein powder is a convenience; creatine has a specific training role.',food:['Include protein foods throughout the day.','Keep carbohydrates to fuel your activity.'],focus:['protein','creatine','vitamin-d'],action:'food'},\n    energy:{title:'Find the reason, not just a pill.',body:'Tiredness can have several causes. It does not tell you which vitamin, if any, you are missing.',food:['Keep meals regular and varied.','Look at sleep and routine alongside what you eat.'],focus:['iron','b12','multivitamin'],action:'check'},\n    gut:{title:'Give your everyday food a look first.',body:'Fibre from different foods is a useful place to start. A probiotic is not a universal gut fix.',food:['Try oats, wholegrains, beans, fruit and veg.','If gut symptoms persist, get advice rather than guessing.'],focus:['probiotics','magnesium','multivitamin'],action:'food'},\n    sleep:{title:'Put the routine ahead of the remedy.',body:'Magnesium is popular, but the sleep evidence is limited. A supplement cannot tell you why your sleep is poor.',food:['Look at caffeine and alcohol near bedtime.','Persistent sleep trouble deserves proper advice.'],focus:['magnesium','multivitamin','vitamin-d'],action:'check'}\n  },\n  supplements:[\n    {id:'vitamin-d',name:'Vitamin D',symbol:'D',base:'consider',evidence:'UK public-health guidance',summary:'A clear seasonal reason to consider it in the UK.',purpose:'Supports normal bone, tooth and muscle health. NHS advice is to consider 10 micrograms (400 IU) daily in autumn and winter; some groups should consider it all year.',food:'Oily fish, egg yolks and some fortified foods contribute, but food alone can make it hard to get enough in winter.',choice:'Check the total vitamin D across your products. A higher dose is not automatically a better choice.',limit:'This is nutritional guidance, not proof of extra energy, fat loss or a testosterone boost.',caution:'Some conditions need individual advice. Follow any dose your clinician has prescribed. The NHS says adults should not take more than 100 micrograms daily; that is a ceiling, not a target.',sources:['vitaminD'],keywords:'vit d winter sunshine bones'},\n    {id:'b12',name:'Vitamin B12',symbol:'B',base:'food',evidence:'UK dietary guidance',summary:'Especially worth checking if you eat a vegan diet.',purpose:'B12 supports normal blood and nervous-system function. Vegan food sources are limited; fortified foods or a supplement may be needed.',food:'Animal foods provide B12. For a vegan diet, check B12-fortified cereals, drinks or nutritional yeast; an unfortified plant food is not a reliable substitute.',choice:'Look at what you actually eat, how often, and the fortification label. A pharmacist or dietitian can help select a suitable option.',limit:'Taking extra B12 is not a general energy boost when your needs are already met.',caution:'Symptoms are not a deficiency test. Diagnosed deficiency, absorption problems or prior stomach surgery need a clinician-led plan.',sources:['vegan','b12'],keywords:'b 12 plant vegan fatigue'},\n    {id:'protein',name:'Protein powder',symbol:'P',base:'food',evidence:'Food & training guidance',summary:'Useful for convenience when food is awkward. Not essential.',purpose:'A simple way to add protein if fitting it into meals is difficult. Adequate protein supports the body’s response to exercise.',food:'Try eggs, yoghurt, fish, chicken, beans or tofu according to your diet. A meal brings more than a scoop of protein.',choice:'Choose a format you tolerate, check allergens and compare protein per serving. Whey, soya or other plant options can suit different diets.',limit:'A powder does not replace varied meals or resistance training. This guide does not calculate a personal protein target.',caution:'Kidney disease or a prescribed diet needs individual advice. A protein shake is not automatically a nutritionally complete meal replacement.',sources:['sport'],keywords:'whey soya soy pea shake muscle'},\n    {id:'creatine',name:'Creatine',symbol:'C',base:'food',evidence:'Established for specific training',summary:'An optional tool for repeated, high-intensity effort.',purpose:'Creatine can improve performance in repeated, high-intensity efforts and support strength-training adaptations. Responses vary.',food:'Food and training are still the foundation. You do not need a creatine tub to start getting stronger.',choice:'Creatine monohydrate is the most studied form. Research commonly uses 3–5g daily after loading, or a slower protocol without loading; that is context, not a personal dose instruction.',limit:'Not a fat burner or a proven all-purpose health upgrade. Evidence from athletic activity does not automatically apply to every goal.',caution:'Water retention can raise scale weight. Discuss suitability with a pharmacist or clinician if you have a condition, take medicines or have kidney concerns.',sources:['creatine'],keywords:'monohydrate gym strength muscle training'},\n    {id:'omega-3',name:'Omega-3',symbol:'Ω',base:'food',evidence:'Outcome-specific, mixed relevance',summary:'Look at your food pattern before buying fish oil.',purpose:'An intake question if you eat little fish, rather than an automatic heart-protection purchase.',food:'The NHS recommends two portions of fish weekly, including one oily fish. Plant foods such as walnuts provide a different omega-3 type.',choice:'If considering a product, read the EPA/DHA amounts rather than just “fish oil” on the front. Vegan algae options exist; ask about suitability.',limit:'A Cochrane review found little or no effect on overall deaths or cardiovascular events, while some coronary outcomes showed small possible benefits with lower certainty. No blanket prevention promise.',caution:'Check with a pharmacist if you take medicines, especially anticoagulants, or are considering high doses. Do not substitute it for prescribed treatment.',sources:['balanced','vegan','omega','omegaSafety'],keywords:'fish oil epa dha algae heart'},\n    {id:'multivitamin',name:'Multivitamin',symbol:'M',base:'food',evidence:'Need depends on diet & context',summary:'Not a licence to eat poorly, and not a must-have for men.',purpose:'May be worth discussing when diet is persistently restricted. Being male, on its own, is not a reason for a daily stack.',food:'Most people can meet nutrient needs through a varied diet, with specific exceptions such as seasonal vitamin D.',choice:'Check amounts per daily serving and overlap with single nutrients. Avoid assuming a long ingredient list means more benefit.',limit:'A multivitamin cannot provide the same benefits as a balanced diet or tell you what you are missing.',caution:'Medicines, health conditions and duplicated ingredients matter. If eating little is ongoing, get help with the cause and nutritional needs rather than treating a tablet as the solution.',sources:['vitamins','supplements'],keywords:'multi vitamins minerals gaps'},\n    {id:'magnesium',name:'Magnesium',symbol:'Mg',base:'food',evidence:'Limited for improving sleep',summary:'A nutrient you need. A sleep cure is another claim.',purpose:'Magnesium has normal roles in the body, but rigorous evidence for treating insomnia is insufficient.',food:'Nuts, spinach and wholemeal bread can contribute. A varied diet can usually supply what you need.',choice:'Identify a reason for taking it first. Different formats and attractive “night” branding do not establish a sleep benefit.',limit:'Sleep studies are small, inconsistent and often low quality. This does not establish reliable benefit for your sleep.',caution:'High supplemental intakes can cause diarrhoea. Ask a pharmacist about medicines and kidney problems before use. Persistent poor sleep needs assessment.',sources:['minerals','sleep'],keywords:'mg sleep insomnia calm cramps'},\n    {id:'probiotics',name:'Probiotics',symbol:'Pr',base:'food',evidence:'Mixed & condition-specific',summary:'Some uses may help. “Gut health” is too broad a promise.',purpose:'There is some evidence for certain symptoms in conditions such as IBS. Benefit depends on the strain, product and problem.',food:'Start with your overall eating pattern and fibre variety. Yoghurt or a capsule is not a substitute for that.',choice:'A trial with one strain does not prove that another shop product works. Discuss persistent symptoms and a suitable trial with a professional.',limit:'Many broad claims have little support. Studies of pharmaceutical-grade products do not automatically validate supermarket supplements.',caution:'Talk to a doctor before using probiotics if you have an existing condition or weakened immune system.',sources:['probiotics'],keywords:'gut bacteria ibs digestion'},\n    {id:'iron',name:'Iron',symbol:'Fe',base:'ask',evidence:'Useful when a need is established',summary:'Do not buy it just because you feel tired.',purpose:'Iron is needed for red blood cells. Deficiency may need treatment, but tiredness alone does not establish iron deficiency.',food:'Beans, nuts, fortified cereals and some meat provide iron. Men can generally meet needs from food.',choice:'If worried about deficiency, ask your GP. Testing and the reason for a deficiency matter, as does the treatment plan.',limit:'Extra iron is not a general performance or energy upgrade for someone with adequate levels.',caution:'Excess can be harmful and cause nausea, pain or constipation. Keep iron away from children. Continue clinician-prescribed treatment as directed.',sources:['iron','fatigue'],keywords:'fe anaemia tired fatigue energy'},\n    {id:'fat-burners',name:'“Fat burners”',symbol:'!',base:'skip',evidence:'Limited benefit, possible harms',summary:'We would not put these ahead of food and proper support.',purpose:'Products promise faster weight loss, but there is little scientific evidence that weight-loss supplements work.',food:'Put your effort into sustainable meals and suitable weight-management support instead of a stimulant stack.',choice:'Do not judge a blend by one ingredient study. Its dose, combination and actual product evidence matter.',limit:'Small, short studies cannot establish reliable long-term weight loss. “Natural” is not proof of safety.',caution:'Some products can cause harm or interact with medicines. Particular care is needed with heart disease, high blood pressure, diabetes or liver disease.',sources:['weight'],keywords:'burner metabolism weight loss slimming detox'},\n    {id:'testosterone',name:'“T-boosters”',symbol:'T',base:'skip',evidence:'Ingredient evidence ≠ blend proof',summary:'A marketing label is not a diagnosis or treatment.',purpose:'Do not use an over-the-counter “testosterone booster” to work out whether your testosterone is low.',food:'Start with the basics and get persistent symptoms assessed. No specific food or supplement stack is offered as a hormone treatment here.',choice:'Ask what outcome has been tested in people, with this exact formula and dose. An ingredient’s role in the body is not proof that extra boosts hormones.',limit:'NIH reports no sex-hormone benefit for tribulus in the small short trials it summarises. This cannot judge every blend, and does not establish benefit for a commercial product.',caution:'Persistent concerns about energy or sexual function deserve clinical advice. Avoid unknown internet blends; check ingredients and medicine interactions.',sources:['creatine','supplements'],keywords:'t booster testosterone hormones men zinc tribulus'}\n  ],\n  meals: {\n    breakfast:{starch:['Porridge oats','Wholemeal toast','Wholegrain cereal'],colour:['Banana','Frozen berries','Tomatoes'],protein:[{name:'Plain yoghurt',diets:['mixed','vegetarian']},{name:'Eggs',diets:['mixed','vegetarian']},{name:'Fortified soya yoghurt',diets:['mixed','vegetarian','vegan']},{name:'Peanut butter',diets:['mixed','vegetarian','vegan']}],instructions:'Use these together or as a main and a side. For oats or cereal, add milk or a fortified alternative. Cook eggs thoroughly; keep chilled foods refrigerated.'},\n    lunch:{starch:['Wholemeal bread','Skin-on jacket potato','Brown rice'],colour:['Frozen mixed veg','Tomatoes and cucumber','Carrots'],protein:[{name:'Tinned tuna',diets:['mixed']},{name:'Eggs',diets:['mixed','vegetarian']},{name:'Tinned beans',diets:['mixed','vegetarian','vegan']},{name:'Tofu',diets:['mixed','vegetarian','vegan']}],instructions:'Make a sandwich, a jacket topping or a rice bowl. Add the veg as a side or stir it through. Cook and store ingredients according to their pack instructions.'},\n    dinner:{starch:['Wholewheat pasta','Brown rice','Skin-on potatoes'],colour:['Frozen mixed veg','Broccoli','Tinned tomatoes'],protein:[{name:'Chicken',diets:['mixed']},{name:'Fish',diets:['mixed']},{name:'Tinned lentils',diets:['mixed','vegetarian','vegan']},{name:'Tofu',diets:['mixed','vegetarian','vegan']}],instructions:'Build a bowl or plate from the three foods. Tinned tomatoes can become a simple sauce. Cook meat and fish thoroughly; follow pack cooking and storage instructions.'}\n  }\n};\n";
export const guideRuntime="(() => {\n  'use strict';\n  const D=window.SHIFT_DATA;\n  const initial=()=>({goal:'basics',diet:'mixed',appetite:'usual',budget:false,training:false,meal:'lunch',mealProtein:'',mealStarch:'',mealColour:'',shortlist:[],compare:[],action:'food',mealPicked:false,search:'',filter:'all'});\n  let state=initial();\n  const $=id=>document.getElementById(id);\n  const esc=v=>String(v).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  const labels={consider:'Worth considering',food:'Food first / optional',ask:'Ask a professional',skip:'Not a priority'};\n  const item=id=>D.supplements.find(s=>s.id===id);\n  const sourceLink=id=>{const s=D.sources[id];return `<a href=\"${esc(s.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(s.name)} ↗</a>`;};\n  function relevance(s,ctx=state){\n    let level=s.base,reason=s.summary;\n    if(s.id==='b12'&&ctx.diet==='vegan'){level='consider';reason='Your vegan choice makes reliable B12 sources a priority to check.';}\n    if(s.id==='protein'&&ctx.appetite!=='usual'){level='food';reason='Smaller meals make protein foods worth planning; powder is an optional convenience.';}\n    if(s.id==='creatine'){level=ctx.training?'consider':'food';reason=ctx.training?'You do strength training: read about its specific role and limitations.':'No regular strength training selected: food and a training routine come first.';}\n    if(s.id==='multivitamin'&&ctx.appetite!=='usual'){level='ask';reason='Ongoing low intake needs a diet or prescriber review, not a guessed nutrient stack.';}\n    if(s.id==='magnesium'&&ctx.goal==='sleep'){level='skip';reason='For better sleep, current evidence is too limited to make this a priority.';}\n    if(s.id==='probiotics'&&ctx.goal==='gut'){level='food';reason='A possible specific use, not a general fix. Persistent symptoms need assessment.';}\n    return {level,reason};\n  }\n  function filtered(ctx=state){\n    const query=ctx.search.trim().toLowerCase();\n    return D.supplements.filter(s=>(!query||(s.name+' '+s.keywords).toLowerCase().includes(query))&&(ctx.filter==='all'||relevance(s,ctx).level===ctx.filter))\n      .sort((a,b)=>{const focus=D.goals[ctx.goal].focus;return (focus.includes(a.id)?focus.indexOf(a.id):99)-(focus.includes(b.id)?focus.indexOf(b.id):99);});\n  }\n  function cost(price,servings,daily){\n    if([price,servings,daily].some(v=>v===''||v===null||v===undefined))return {empty:true};\n    const [p,s,d]=[Number(price),Number(servings),Number(daily)];\n    if(![p,s,d].every(Number.isFinite)||p<0||p>10000||!Number.isInteger(s)||s<1||s>100000||d<=0||d>100)return {error:true};\n    return {perDay:p/s*d,monthly:p/s*d*30,lasts:s/d};\n  }\n  function announce(text){$('announcer').textContent=text;}\n  function renderStart(){\n    const g=D.goals[state.goal];\n    let context='';\n    if(state.diet==='vegan')context+='For a vegan diet, check reliable B12 sources and the fortification of dairy alternatives. Other nutrients may need attention too. '+sourceLink('vegan')+' ';\n    if(state.diet==='vegetarian')context+='Keep variety across protein foods and check fortified alternatives when avoiding dairy. '+sourceLink('balanced')+' ';\n    if(state.appetite==='glp1')context+='On a GLP-1: keep smaller meals regular, include protein and seek prescriber help if you feel unwell or cannot eat properly. '+sourceLink('glp1')+' ';\n    else if(state.appetite==='smaller')context+='If low appetite persists or weight loss is unexplained, speak to your GP. This choice does not show that you have a deficiency. '+sourceLink('fatigue')+' ';\n    if(state.budget)context+='Cupboard-friendly meal options are selected below: beans or lentils, wholegrains and frozen or tinned produce.';\n    const caution=(state.goal==='energy')?`<p><strong>Tired for weeks, or it affects daily life?</strong> Book a GP assessment. Supplements should not delay it. ${sourceLink('fatigue')}</p>`:(state.goal==='sleep'?`<p>Look at a regular sleep time and caffeine near bedtime. ${sourceLink('fatigue')}</p>`:'');\n    $('starting-result').innerHTML=`<div><p class=\"eyebrow\">YOUR FOOD-FIRST START</p><h3>${esc(g.title)}</h3><p>${esc(g.body)}</p>${caution}</div><div><p class=\"eyebrow\">TRY THIS BEFORE A TUB</p><ul>${g.food.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class=\"small\">A guide to what to explore, not a calculation of your nutritional needs.</p><a class=\"text-link\" href=\"#food\">Build one useful meal →</a></div>${context?`<p class=\"context-message\">${context}</p>`:''}`;\n  }\n  function renderShelf(){\n    const list=filtered();\n    $('result-count').textContent=`${list.length} of ${D.supplements.length} options · relevance reflects your selections above.`;\n    $('supplement-grid').innerHTML=list.length?list.map(s=>{\n      const r=relevance(s);\n      return `<article class=\"supp-card\"><div class=\"supp-top\"><span class=\"status-badge status-${r.level}\">${labels[r.level]}</span><span class=\"supp-symbol\" aria-hidden=\"true\">${esc(s.symbol)}</span></div><h3>${esc(s.name)}</h3><p class=\"supp-reason\">${esc(r.reason)}</p><p class=\"evidence-label\">${esc(s.evidence)}</p><button class=\"read-button\" data-detail=\"${s.id}\" aria-haspopup=\"dialog\">Read the straight answer <span aria-hidden=\"true\">↗</span><span class=\"sr-only\"> about ${esc(s.name)}</span></button><div class=\"card-actions\"><button data-shortlist=\"${s.id}\" aria-pressed=\"${state.shortlist.includes(s.id)}\" aria-label=\"${state.shortlist.includes(s.id)?'Remove':'Add'} ${esc(s.name)} ${state.shortlist.includes(s.id)?'from':'to'} reading shortlist\">${state.shortlist.includes(s.id)?'Shortlisted ✓':'+ Shortlist'}</button><button data-compare=\"${s.id}\" aria-pressed=\"${state.compare.includes(s.id)}\" aria-label=\"${state.compare.includes(s.id)?'Remove':'Add'} ${esc(s.name)} ${state.compare.includes(s.id)?'from':'to'} comparison\" ${state.compare.length===2&&!state.compare.includes(s.id)?'disabled':''}>${state.compare.includes(s.id)?'Comparing ✓':'Compare'}</button></div></article>`;\n    }).join(''):`<div class=\"empty-state\"><h3>No matches this time.</h3><p>Try another name or usefulness level.</p><button class=\"button secondary\" data-clear-filter>Clear search and filter</button></div>`;\n    renderCompare();\n  }\n  function renderCompare(){\n    $('comparison-panel').hidden=state.compare.length===0;\n    $('comparison-content').innerHTML=state.compare.length===1?'<p class=\"small\">Choose one more “Compare” button to see two options together.</p>':state.compare.map(id=>{const s=item(id),r=relevance(s);return `<article><h3>${esc(s.name)}</h3><div class=\"compare-cell\"><strong>USEFULNESS IN YOUR CONTEXT</strong>${labels[r.level]}<p>${esc(r.reason)}</p></div><div class=\"compare-cell\"><strong>EVIDENCE</strong>${esc(s.evidence)}<p>${esc(s.limit)}</p></div><div class=\"compare-cell\"><strong>FOOD & PRACTICAL CHOICE</strong>${esc(s.food)}<p>${esc(s.choice)}</p></div><div class=\"compare-cell\"><strong>CAUTIONS</strong>${esc(s.caution)}</div><div class=\"compare-cell\">${s.sources.map(sourceLink).join(' · ')}</div></article>`;}).join('');\n    $('comparison-content').className=state.compare.length===2?'compare-grid':'';\n  }\n  function mealChoices(){\n    const m=D.meals[state.meal];\n    return {protein:m.protein.filter(p=>p.diets.includes(state.diet)).map(p=>p.name),starch:m.starch,colour:m.colour};\n  }\n  function renderMealOptions(reset=false){\n    const choices=mealChoices();\n    for(const [key,list] of Object.entries(choices)){\n      const prop='meal'+key[0].toUpperCase()+key.slice(1);\n      if(reset||!list.includes(state[prop])){\n        state[prop]=list[0];\n        if(state.budget&&key==='protein')state[prop]=list.find(v=>/Tinned|Peanut/.test(v))||list[0];\n      }\n      $('meal-'+key).innerHTML=list.map(v=>`<option value=\"${esc(v)}\" ${state[prop]===v?'selected':''}>${esc(v)}</option>`).join('');\n    }\n    renderMeal();\n  }\n  function mealName(){return `${state.mealProtein} + ${state.mealStarch.toLowerCase()} + ${state.mealColour.toLowerCase()}`;}\n  function renderMeal(){\n    $('meal-title').textContent=mealName();\n    $('meal-instructions').textContent=D.meals[state.meal].instructions;\n    $('meal-tags').innerHTML=`<span class=\"tag\">${state.meal.toUpperCase()}</span><span class=\"tag\">${state.diet==='vegan'?'VEGAN':state.diet==='vegetarian'?'VEGETARIAN':'YOUR FOOD CHOICE'}</span>${state.budget?'<span class=\"tag\">CUPBOARD FRIENDLY</span>':''}`;\n    $('shopping-list').innerHTML=[state.mealProtein,state.mealStarch,state.mealColour].map(v=>`<label class=\"shopping-item\"><input type=\"checkbox\"><span>${esc(v)}</span></label>`).join('');\n    $('meal-status').textContent=state.mealPicked?'This meal is in your takeaway.':'';\n    if(state.mealPicked)renderPlan();\n  }\n  const actions={food:{title:'Make one useful meal.',body:'Use the meal idea as a starting point for this week. Adjust it to your appetite, dietary needs and what you have in.'},read:{title:'Read before you buy.',body:'Use the straight answers and source links to check whether there is a specific purpose for any supplement you are considering.'},check:{title:'Ask the right person.',body:'Take your questions and any supplement labels to a pharmacist, GP or registered dietitian. If symptoms are persistent, ask for assessment rather than guessing the cause.'},nothing:{title:'Buy nothing for now.',body:'That is a valid decision. Keep the food basics in place and revisit a supplement only when there is a clear job for it.'}};\n  function renderActions(){\n    $('action-options').innerHTML='<legend>Choose your next step</legend>'+Object.entries(actions).map(([id,a])=>`<label class=\"action-choice\"><input type=\"radio\" name=\"action\" value=\"${id}\" ${state.action===id?'checked':''}><span>${esc(a.title)}<small>${id==='food'?'Try the meal you built.':id==='read'?'Check purpose and evidence.':id==='check'?'Get suitability or symptoms checked.':'Keep it simple. Spend nothing on supplements today.'}</small></span></label>`).join('');\n  }\n  function renderPlan(){\n    const a=actions[state.action];\n    $('plan-title').textContent=a.title;\n    $('plan-body').textContent=a.body+(state.action==='food'?' Your meal idea: '+mealName()+'.':'');\n    $('shortlist').innerHTML=state.shortlist.length?state.shortlist.map(id=>{const s=item(id);return `<div class=\"shortlist-item\"><span>${esc(s.name)} <small>· ${labels[relevance(s).level]}</small></span><button class=\"text-button\" data-remove=\"${id}\" aria-label=\"Remove ${esc(s.name)} from reading shortlist\">Remove</button></div>`;}).join(''):'<p class=\"small\">Nothing shortlisted. You do not need to add anything.</p>';\n    $('download-status').textContent='';\n  }\n  function updateContext(resetMeal=false){renderStart();renderMealOptions(resetMeal);renderShelf();renderActions();renderPlan();}\n  let lastDialogId=null;\n  function showDetail(id){\n    const s=item(id);if(!s)return;\n    lastDialogId=id;const r=relevance(s);\n    $('detail-content').innerHTML=`<span class=\"status-badge status-${r.level}\">${labels[r.level]}</span><h2 id=\"detail-title\" class=\"dialog-title\">${esc(s.name)}</h2><p class=\"detail-context\">${esc(r.reason)}</p><p class=\"detail-evidence\">${esc(s.evidence)}</p><div class=\"detail-grid\"><div><h3>What it may do</h3><p>${esc(s.purpose)}</p></div><div><h3>Start with food</h3><p>${esc(s.food)}</p></div><div><h3>If you are considering it</h3><p>${esc(s.choice)}</p></div><div><h3>What the evidence doesn’t say</h3><p>${esc(s.limit)}</p></div></div><div class=\"detail-caution\"><strong>Before you take it</strong><p>${esc(s.caution)}</p><p>Follow your clinician’s advice and any prescribed treatment.</p></div><div class=\"detail-sources\"><strong>Read the evidence · checked 12 October 2026</strong>${s.sources.map(sourceLink).join('')}</div><div class=\"detail-footer\"><button class=\"button primary\" data-detail-shortlist=\"${s.id}\">${state.shortlist.includes(s.id)?'Remove from reading shortlist':'+ Add to reading shortlist'}</button><button class=\"button secondary\" data-close-detail>Back to the guide</button></div>`;\n    if(!$('detail-dialog').open)$('detail-dialog').showModal();\n  }\n  function toggleShortlist(id){\n    if(!item(id))return;\n    state.shortlist=state.shortlist.includes(id)?state.shortlist.filter(x=>x!==id):[...state.shortlist,id];\n    renderShelf();renderPlan();announce(item(id).name+(state.shortlist.includes(id)?' added to':' removed from')+' reading shortlist.');\n  }\n  function takeaway(ctx=state){\n    const a=actions[ctx.action],meal=`${ctx.mealProtein} + ${ctx.mealStarch.toLowerCase()} + ${ctx.mealColour.toLowerCase()}`;\n    const ids=new Set(['balanced','supplements',...(ctx.appetite==='glp1'?['glp1']:[])]);\n    const lines=ctx.shortlist.map(id=>{const s=item(id);s.sources.forEach(k=>ids.add(k));const r=relevance(s,ctx);return `- ${s.name}: ${labels[r.level]}\\n  ${r.reason}\\n  Evidence: ${s.evidence}. ${s.limit}\\n  Caution: ${s.caution}`;});\n    return `SHIFT SOME TIMBER — MY TAKEAWAY\\nContent checked: 12 October 2026\\n\\nFocus: ${D.goals[ctx.goal].title}\\nDiet context: ${ctx.diet}; appetite: ${ctx.appetite==='glp1'?'smaller while using a GLP-1':ctx.appetite==='smaller'?'smaller / eating less':'about usual'}\\n\\nMY NEXT STEP\\n${a.title}\\n${a.body}\\n\\nMEAL IDEA (${ctx.meal})\\n${meal}\\nShopping list: ${ctx.mealProtein}, ${ctx.mealStarch}, ${ctx.mealColour}.\\nAdjust portions to your needs; check allergens and cooking/storage instructions.\\n\\nREADING SHORTLIST — NOT AN INSTRUCTION TO TAKE\\n${lines.length?lines.join('\\n\\n'):'Nothing shortlisted. Buying nothing is a valid choice.'}\\n\\nBEFORE BUYING\\nGeneral adult information, not diagnosis or a prescription. Check purpose, dose, duplicated ingredients, allergens and medicine interactions. If you take medicines, have a condition or need a special diet, ask your pharmacist, GP or dietitian. Keep following prescribed treatment. Persistent symptoms need assessment; contact your prescriber promptly if unwell on a GLP-1.\\n\\nSOURCES\\n${[...ids].map(id=>`${D.sources[id].name}\\n${D.sources[id].url}\\n${D.sources[id].date}`).join('\\n\\n')}\\n\\nYour choices were used in this tab only. This takeaway was not sent to SHIFT or saved to My Timber.\\n`;\n  }\n  function renderCost(){\n    const c=cost($('price').value,$('servings').value,$('daily').value),out=$('cost-result');out.classList.toggle('error',!!c.error);\n    out.textContent=c.empty?'Enter the three figures to compare cost.':c.error?'Use a price of £0–£10,000, a whole number of servings (1–100,000), and daily servings above 0 and up to 100.':`£${c.perDay.toFixed(2)} per day · £${c.monthly.toFixed(2)} per 30 days · pack lasts about ${c.lasts.toFixed(1)} days`;\n  }\n  document.addEventListener('click',e=>{\n    const b=e.target.closest('button');if(!b||b.disabled)return;\n    if(b.dataset.sfgGoal){state.goal=b.dataset.sfgGoal;state.action=D.goals[state.goal].action;state.mealPicked=false;document.querySelectorAll('[data-sfg-goal]').forEach(x=>{const yes=x.dataset.sfgGoal===state.goal;x.classList.toggle('active',yes);x.setAttribute('aria-pressed',String(yes));});updateContext();}\n    if(b.dataset.sfgMeal){state.meal=b.dataset.sfgMeal;document.querySelectorAll('[data-sfg-meal]').forEach(x=>{const yes=x.dataset.sfgMeal===state.meal;x.classList.toggle('active',yes);x.setAttribute('aria-pressed',String(yes));});renderMealOptions(true);renderPlan();}\n    if(b.dataset.detail)showDetail(b.dataset.detail);\n    if(b.dataset.shortlist){const id=b.dataset.shortlist;toggleShortlist(id);document.querySelector(`[data-shortlist=\"${id}\"]`)?.focus();}\n    if(b.dataset.detailShortlist){toggleShortlist(b.dataset.detailShortlist);showDetail(b.dataset.detailShortlist);document.querySelector('[data-detail-shortlist]')?.focus();}\n    if(b.dataset.remove){toggleShortlist(b.dataset.remove);$('plan-title').setAttribute('tabindex','-1');$('plan-title').focus();}\n    if(b.dataset.compare){const id=b.dataset.compare;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<2)state.compare.push(id);renderShelf();document.querySelector(`[data-compare=\"${id}\"]`)?.focus();announce(`${state.compare.length} of 2 comparison options selected.`);}\n    if(b.hasAttribute('data-clear-filter')){state.search='';state.filter='all';$('search').value='';$('filter').value='all';renderShelf();$('search').focus();}\n    if(b.hasAttribute('data-close-detail'))$('detail-dialog').close();\n  });\n  for(const id of ['diet','appetite','budget','training'])$(id).addEventListener('change',()=>{state[id]=['budget','training'].includes(id)?$(id).checked:$(id).value;updateContext(id==='diet'||id==='budget');});\n  $('search').addEventListener('input',()=>{state.search=$('search').value;renderShelf();});\n  $('filter').addEventListener('change',()=>{state.filter=$('filter').value;renderShelf();});\n  for(const key of ['protein','starch','colour'])$('meal-'+key).addEventListener('change',()=>{state['meal'+key[0].toUpperCase()+key.slice(1)]=$('meal-'+key).value;renderMeal();renderPlan();});\n  $('action-options').addEventListener('change',e=>{if(actions[e.target.value]){state.action=e.target.value;state.mealPicked=e.target.value==='food';renderPlan();}});\n  $('use-meal').addEventListener('click',()=>{state.action='food';state.mealPicked=true;renderActions();renderPlan();$('meal-status').textContent='This meal is in your takeaway.';document.querySelector('#next').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('plan-title').setAttribute('tabindex','-1');$('plan-title').focus({preventScroll:true});});\n  $('clear-compare').addEventListener('click',()=>{state.compare=[];renderShelf();$('supplements').setAttribute('tabindex','-1');$('supplements').focus();announce('Comparison cleared.');});\n  $('close-dialog').addEventListener('click',()=>$('detail-dialog').close());\n  $('detail-dialog').addEventListener('click',e=>{if(e.target===$('detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});\n  $('detail-dialog').addEventListener('close',()=>document.querySelector(`[data-detail=\"${lastDialogId}\"]`)?.focus());\n  for(const id of ['price','servings','daily'])$(id).addEventListener('input',renderCost);\n  $('cost-form').addEventListener('submit',e=>e.preventDefault());\n  $('cost-example').addEventListener('click',()=>{$('price').value='18';$('servings').value='60';$('daily').value='1';renderCost();});\n  $('download').addEventListener('click',()=>{const blob=new Blob([takeaway()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SHIFT-my-food-and-supplements-takeaway.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('download-status').textContent='Takeaway prepared. Your browser handles the download.';});\n  $('print').addEventListener('click',()=>window.print());\n  $('reset').addEventListener('click',()=>{state=initial();for(const id of ['diet','appetite','filter'])$(id).value=state[id];$('search').value='';for(const id of ['budget','training'])$(id).checked=false;for(const id of ['price','servings','daily'])$(id).value='';document.querySelectorAll('[data-sfg-goal]').forEach(x=>{const yes=x.dataset.sfgGoal===state.goal;x.classList.toggle('active',yes);x.setAttribute('aria-pressed',String(yes));});document.querySelectorAll('[data-sfg-meal]').forEach(x=>{const yes=x.dataset.sfgMeal===state.meal;x.classList.toggle('active',yes);x.setAttribute('aria-pressed',String(yes));});updateContext(true);renderCost();announce('All choices reset.');$('start').setAttribute('tabindex','-1');$('start').focus();});\n  $('sources').innerHTML=Object.values(D.sources).map(s=>`<div class=\"source-item\"><a href=\"${esc(s.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(s.name)} ↗</a><span>${esc(s.date)}</span><span>${esc(s.scope)}</span></div>`).join('');\n  updateContext(true);\n  // Pure functions exposed for finite logic QA; no user records or network calls.\n  window.SHIFT_GUIDE={relevance,filtered,cost,takeaway,initial};\n})();\n";
